  getAvailableActions(order) {
    const actions = [];
    switch (order.status) {
      case OrderStatus.PENDING:
        actions.push('Accept', 'Cancel');
        break;
      case OrderStatus.PROCESSING:
        actions.push('Ship', 'Cancel');
        break;
      case OrderStatus.SHIPPED:
        actions.push('Deliver', 'Cancel');
        break;
      case OrderStatus.DELIVERED:
        actions.push('View Details'); // No further actions
        break;
      case OrderStatus.CANCELLED:
        actions.push('View Details'); // No further actions
        break;
    }
    return actions;
  }
  // Check if action is available for an order
  canPerformAction(order, action) {
    const availableActions = this.getAvailableActions(order);
    return availableActions.includes(action);
  }
  // Get status history for an order
  getStatusHistory(order) {
    return order.statusHistory || [];
  }
  // Format status history for display
  formatStatusHistory(history) {
    if (!history || history.length === 0) {
      return 'No status changes recorded';
    }
    return history.map(change => `${change.fromStatus} → ${change.toStatus} by ${change.changedBy} on ${new Date(change.changedAt).toLocaleString()}`).join('\n');
  }
  closeModal() {
    this.showModal = false;
    this.selectedOrder = null;
  }
  getStatusBadgeClass(status) {
    switch (status) {
      case OrderStatus.PENDING:
        return 'bg-warning';
      case OrderStatus.PROCESSING:
        return 'bg-info';
      case OrderStatus.SHIPPED:
        return 'bg-primary';
      case OrderStatus.DELIVERED:
        return 'bg-success';
      case OrderStatus.CANCELLED:
        return 'bg-danger';
      default:
        return 'bg-secondary';
    }
  }
  getStatusDisplay(status) {
    console.log(`Getting status display for: ${status}`);
    switch (status) {
      case OrderStatus.PENDING:
        return 'Pending';
      case OrderStatus.PROCESSING:
        return 'Processing';
      case OrderStatus.SHIPPED:
        return 'Shipped';
      case OrderStatus.DELIVERED:
        return 'Delivered';
      case OrderStatus.CANCELLED:
        return 'Cancelled';
      default:
        console.log(`Unknown status: ${status}`);
        return status;
    }
  }
  getStatusIcon(status) {
    switch (status) {
      case OrderStatus.PENDING:
        return 'bi-clock';
      case OrderStatus.PROCESSING:
        return 'bi-gear';
      case OrderStatus.SHIPPED:
        return 'bi-truck';
      case OrderStatus.DELIVERED:
        return 'bi-check-circle';
      case OrderStatus.CANCELLED:
        return 'bi-x-circle';
      default:
        return 'bi-question-circle';
    }
  }
  getTotalItems(order) {
    return order.items.reduce((total, item) => total + item.quantity, 0);
  }
  getOrderStatuses() {
    return Object.values(OrderStatus);
  }
  filterOrders() {
    let filtered = this.orders;
