    console.log('Creating test order...');
    const testCartItems = [{
      productId: 'test-1',
      name: 'Test Product 1',
      price: 99.99,
      quantity: 2,
      image: 'assets/images/placeholder.png'
    }];
    const order = this.orderService.createOrder(testCartItems);
    if (order) {
      console.log('Test order created:', order.id);
      this.refreshOrders();
    } else {
      console.log('Failed to create test order');
    }
  }
